import{z as s,x as A,o as t,c as d,q as l,j as o,D as E,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"难负例挖掘","description":"","frontmatter":{"title":"难负例挖掘","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hard-negatives.md","filePath":"llm/hard-negatives.md","lastUpdated":1791063341000}'),p={name:"llm/hard-negatives.md"};function h(m,a,f,u,D,_){const n=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="难负例挖掘" tabindex="-1">难负例挖掘 <a class="header-anchor" href="#难负例挖掘" aria-label="Permalink to &quot;难负例挖掘&quot;">​</a></h1><div class="epigraph"><p>批内随机负例太容易，模型学会的是主题分类。要把「看起来像、其实不答」的文档挖出来，度量才进入细粒度。</p><footer>—— Karpukhin 等 DPR 的 BM25 负例；Xiong 等 ANCE 的用当前模型挖负例</footer></div><p><a href="/llm/contrastive-infonce">上一课</a>的 InfoNCE 梯度由高分负例主导。随机批内负例分数往往很低，梯度接近零。本课写难负例。缺口是训练分布：负例从哪来、何时会变成假负。后课 Matryoshka 默认空间已经靠难负例撑开，而不是靠加维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Karpukhin 的 DPR 用 BM25 检索到的高分但标注不相关的段落当负例，比随机负例强。静态挖一次会过时：模型更新后，难例集合不再难。Xiong 等 ANCE 用当前检查点异步建索引、检索难负例，空间跟着模型走。RocketQA 等再引入交叉编码器去假负：双塔认为难、交叉编码器认为相关的，不当负例。</p><p><span class="marginnote">术语翻译：负例就是训练时「配错对」的样本，用来教模型拉开距离。难负例是其中「看着很像正例」的那种；假负例更糟——标注说不相关、其实相关（如同义改写），把它当负例会把正确答案硬推远，直接伤召回。</span></p><p>假负例会伤害召回：同义改写被推远。只追「最难」还会不稳定，损失被少数噪声对主导。需要混合：随机、BM25、模型挖到的、以及少量金标难负。</p><p><span class="marginnote">难负例不是越多越难越好。验证应看细粒度对（易混淆实体、相反极性），不是只看主题级召回。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线：用现索引对训练查询取 Top-\\(n\\) 非正例 → 可选交叉编码器过滤 → 与批内随机负例混合进 InfoNCE。更新频率：过勤则索引抖动、过慢则负例变易。文档侧挖掘（对每个文档找易混查询）对称可用。标注预算应花在「双塔高分、标注员说不相关」的切片上。</p><p><span class="marginnote">数字感受配比：一条查询的 InfoNCE 里可能是 1 个正例、上百个批内随机负例、再混一两个挖来的难负例。难负例占比很小，但它们分数最高、梯度最大——少数标错的难负就能主导整个 batch 的更新方向，所以要靠随机负例压舱。</span></p>',11)),(t(),o(B,null,{default:E(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AE%AD%E7%BB%83%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20RET%5B%22%E5%BD%93%E5%89%8D%E6%A3%80%E7%B4%A2%E5%99%A8%20Top-n%22%5D%0A%20%20RET%20--%3E%20FIL%5B%22%E4%BA%A4%E5%8F%89%E7%BC%96%E7%A0%81%E5%99%A8%E5%8E%BB%E5%81%87%E8%B4%9F%22%5D%0A%20%20FIL%20--%3E%20MIX%5B%22%E4%B8%8E%E9%9A%8F%E6%9C%BA%E8%B4%9F%E4%BE%8B%E6%B7%B7%E5%90%88%22%5D%0A%20%20MIX%20--%3E%20L%5B%22InfoNCE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"随机负例只要求 \\(z_q\\) 离开无关主题的云团。难负例要求在同一主题云团内部把正确段落与近邻段落分开，于是表示必须编码约束、实体与极性。ANCE 的异步更新是在对正在移动的流形做近似硬负采样；延迟过大，挖到的是旧流形上的难例，对新模型又变易。",-1)),a[5]||(a[5]=e("p",null,"两类负例在表示空间里逼模型学的东西不同：",-1)),(t(),o(B,null,{default:E(()=>[i(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%20z_q%22%5D%20--%3E%20RN%5B%22%E9%9A%8F%E6%9C%BA%E8%B4%9F%E4%BE%8B%3A%20%E5%88%AB%E7%9A%84%E4%B8%BB%E9%A2%98%E4%BA%91%E5%9B%A2%22%5D%0A%20%20Q%20--%3E%20HN%5B%22%E9%9A%BE%E8%B4%9F%E4%BE%8B%3A%20%E5%90%8C%E4%B8%80%E4%BA%91%E5%9B%A2%E5%86%85%E7%9A%84%E8%BF%91%E9%82%BB%E6%AE%B5%E8%90%BD%22%5D%0A%20%20RN%20--%3E%20E1%5B%22%E6%8E%A8%E5%BC%80%E5%8D%B3%E5%8F%AF%2C%20%E5%AD%A6%E5%88%B0%E7%9A%84%E5%8F%AA%E6%98%AF%E4%B8%BB%E9%A2%98%E5%88%86%E7%B1%BB%22%5D%0A%20%20HN%20--%3E%20E2%5B%22%E5%BF%85%E9%A1%BB%E5%9C%A8%E4%BA%91%E5%9B%A2%E5%86%85%E5%88%86%E7%BB%86%3A%20%E5%AE%9E%E4%BD%93%E3%80%81%E7%BA%A6%E6%9D%9F%E3%80%81%E6%9E%81%E6%80%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有标注时，交叉编码器本身会错，去假负会去掉真难例。应抽检。下一课 Matryoshka：同一套对比目标下，如何让截断后的短向量仍然可用。</p><p><span class="marginnote">常见误区：以为负例越难越好、一路拉到最难。损失被少数最难（也可能是标错的）样本主导后训练会震荡；索引更新太勤，挖到的「难例」还跟着旧模型一起抖。难度要靠混合比例调，不是拉满。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>难负例把对比学习从主题分类推进到细粒度匹配。</li><li>静态 BM25 负例会过时；用当前模型挖并去假负。</li><li>与随机负例混合，避免被噪声对主导。</li><li>出处：Karpukhin 等 DPR；Xiong 等 ANCE；RocketQA 去假负。</li></ul>',5))])}const F=s(p,[["render",h]]);export{C as __pageData,F as default};
